typedef struct {
  struct pool_rec *pool;

  volatile int sf_flags;                /* Session/State flags */
  volatile int sp_flags;                /* Session/Protection flags */

  pr_netaddr_t data_addr;               /* Remote data address */
  unsigned short data_port;             /* Remote data port */

  const char *auth_mech;                /* Name of the authentication
                                         * module/mechanism that successfully
                                         * authenticated the client
                                         */

  const char *rfc2228_mech;             /* RFC2228 authentication mechanism
                                         * used
                                         */

  char cwd[PR_TUNABLE_PATH_MAX];        /* Current working directory */
  char vwd[PR_TUNABLE_PATH_MAX];        /* Current virtual working directory */

  struct config_struc *dir_config;      /* Closest matching configuration
                                         * for current operation
                                         */

  /* Process ID of the session */
  pid_t pid;

  /* The uid/gids are manipulated by the PRIVS macros in
   * privs.h
   */

  int disable_id_switching;             /* Disable UID/GID switching */
  uid_t uid, ouid;                      /* Current and original UIDs */
  gid_t gid;                            /* Current GID */

  array_header *gids;
  array_header *groups;

  /* fsuid/fsgid are used for automagic chown after creation or upload.
   * They are initially -1, meaning no chown/chgrp.
   */
  uid_t fsuid;                           /* Saved file UID */
  gid_t fsgid;                           /* Saved file GID */

  const char *user, *group;              /* Username/groupname after login */
  const char *user_homedir;             /* Home directory of user before chroot
                                         */
  uid_t login_uid;                      /* UID after login, but before
                                         * session.uid is changed
                                         */
  gid_t login_gid;                      /* GID after login, but before
                                         * session.gid is changed
                                         */

  pr_table_t *notes;                    /* Session notes table */

  const struct class_struc *conn_class; /* Session class */
  const char *proc_prefix;              /* The "prefix" of our process name */

  int wtmp_log;                         /* Are we logging to wtmp? */

  struct conn_struc *c;                 /* Control connection */
  struct conn_struc *d;                 /* Data connection */

  int hide_password;                    /* Hide password in logs/ps listing */

  const char *chroot_path;              /* Chroot directory */

  struct config_struc *anon_config;     /* Anonymous FTP configuration */
  const char *anon_user;                /* Email address sent to us */

  const char *curr_cmd;                 /* Current FTP command */
  int curr_cmd_id;                      /* Current FTP command ID */
  struct cmd_struc *curr_cmd_rec;       /* Current command */

  int curr_phase;                       /* Current handler phase */

  struct server_struc *prev_server;     /* Previous server_rec, if HOST changed
                                         * the main_server pointer.
                                         */

  off_t restart_pos;                    /* Restart marked position (REST) */
  off_t range_start, range_len;         /* Transfer range (RANG) */

  struct {
    struct pool_rec *p;

    int xfer_type;     /* xfer session attributes, default/append/hidden */
    int direction;
    const char *filename;               /* As shown to user */
    const char *path;                   /* As used in transfer */
    const char *path_hidden;            /* As used in hidden stor */

    unsigned int bufsize, buflen;

    struct timeval start_time;          /* Time current transfer started */
    off_t file_size;                    /* Total size of file (if known) */
    off_t total_bytes;                  /* Total bytes transferred */

    char *bufstart, *buf;
  } xfer;

  /* Total number of bytes uploaded in this session. */
  off_t total_bytes_in;

  /* Total number of bytes downloaded in this session. */
  off_t total_bytes_out;

  /* Total number of bytes transferred in this session. */
  off_t total_bytes;

  /* Total number of files uploaded in this session. */
  unsigned int total_files_in;

  /* Total number of files downloaded in this session. */
  unsigned int total_files_out;

  /* Total number of files transferred (both uploaded and downloaded) in
   * this session.
   */
  unsigned int total_files_xfer;

  /* Total number of "raw" protocol bytes read in from the network for
   * the session.
   */
  off_t total_raw_in;

  /* Total number of "raw" protocol bytes written out to the network for
   * the session.
   */
  off_t total_raw_out;

  /* Reason code for end of session/disconnection; in reality, the values
   * come from the pr_disconnect_reason_e enum in session.h.
   */
  int disconnect_reason;

  /* Module which disconnected/ended the session */
  struct module_struc *disconnect_module;

  /* Start/connect time of the session, in milliseconds since epoch. */
  uint64_t connect_time_ms;

} session_t;

typedef struct ipbind_rec {
  struct ipbind_rec *ib_next;

  /* IP address to which this binding is "bound" */
  const pr_netaddr_t *ib_addr;
  unsigned int ib_port;

  /* Default server to handle requests to this binding.  If namebinds are
   * present, they will be checked before using this server
   */
  server_rec *ib_server;

  /* Listener associated with this binding.  This listener, and
   * ib_server->listen, are the same listener.  The duplicate locations
   * are necessary for inetd-run servers (at present).
   */
  conn_t *ib_listener;

  /* List of name-based servers bound to the above IP address.  Note that
   * if this functionality becomes widely adopted and used, a more efficient
   * search-and-lookup mechanism will be needed, for performance reasons.
   */
  array_header *ib_namebinds;

  /* If this binding is the DefaultServer binding */
  unsigned char ib_isdefault;

  /* If this binding handles localhost requests */
  unsigned char ib_islocalhost;

  /* If this binding is active */
  unsigned char ib_isactive;

} pr_ipbind_t;

typedef struct namebind_rec {
  const char *nb_name;
  unsigned char nb_iswildcard;
  unsigned char nb_isactive;
  server_rec *nb_server;
  unsigned int nb_server_port;

} pr_namebind_t;

typedef enum {
	JSON_NULL,
	JSON_BOOL,
	JSON_STRING,
	JSON_NUMBER,
	JSON_ARRAY,
	JSON_OBJECT,
} JsonTag;

struct json_node_st
{
	/* only if parent is an object or array (NULL otherwise) */
	struct json_node_st *parent;
	struct json_node_st *prev, *next;

	/* only if parent is an object (NULL otherwise) */
	char *key; /* Must be valid UTF-8. */

	JsonTag tag;
	union {
		/* JSON_BOOL */
		int bool_;

		/* JSON_STRING */
		char *string_; /* Must be valid UTF-8. */

		/* JSON_NUMBER */
		double number_;

		/* JSON_ARRAY */
		/* JSON_OBJECT */
		struct {
			struct json_node_st *head, *tail;
		} children;
	};
};

typedef struct child {
  struct child *next, *prev;

  pool *ch_pool;
  pid_t ch_pid;
  time_t ch_when;
  int ch_pipefd;

  unsigned char ch_dead;
} pr_child_t;

typedef struct class_struc {
  pool *cls_pool;
  char *cls_name;
  unsigned int cls_satisfy;
  array_header *cls_acls;
  pr_table_t *cls_notes;

  struct class_struc *cls_next;
} pr_class_t;

typedef struct config_struc config_rec;
struct server_struc;

struct config_struc {
  struct config_struc *next, *prev;

  int config_type;
  unsigned int config_id;

  struct pool_rec *pool;	/* Memory pool for this object */
  xaset_t *set;			/* The set we are stored in */
  char *name;
  unsigned int argc;
  void **argv;

  long flags;			/* Flags */

  struct server_struc *server;	/* Server this config element is attached to */
  config_rec *parent;		/* Our parent configuration record */
  xaset_t *subset;		/* Sub-configuration */
};

typedef struct cl_obj {
  struct cl_obj *cl_next, *cl_prev;

  /* Pool for this object's use */
  pool *cl_pool;

  /* Client socket file descriptor */
  int cl_fd;

  /* Credentials of the connecting client */
  uid_t cl_uid;
  const char *cl_user;
  gid_t cl_gid;
  const char *cl_group;
  pid_t cl_pid;

  /* For internal use only */
  volatile unsigned long cl_flags;

  /* Pointers to all controls matching client request */
  array_header *cl_ctrls;

} pr_ctrls_cl_t;

typedef struct ctrls_obj {
  struct ctrls_obj *ctrls_next, *ctrls_prev;

  /* Object ID */
  unsigned int ctrls_id;

  /* Registering module */
  const module *ctrls_module;

  /* Requesting client */
  pr_ctrls_cl_t *ctrls_cl;

  /* Control "action" */
  const char *ctrls_action;

  /* Control trigger time.  If 0, triggers immediately */
  time_t ctrls_when;

  /* Simple description/help text */
  const char *ctrls_desc;

  /* Temporary pool */
  pool *ctrls_tmp_pool;

  /* Control handler callback */
  int (*ctrls_cb)(struct ctrls_obj *, int, char **);

  /* Control handler callback arguments */
  array_header *ctrls_cb_args;

  /* Control handler callback return value.  Used to determine when to clear
   * this object from the requested list
   */
  int ctrls_cb_retval;

  /* Control handler callback responses */
  array_header *ctrls_cb_resps;

  /* For possibly passing data among control handlers */
  void *ctrls_data;

  /* For internal use */
  volatile unsigned long ctrls_flags;

} pr_ctrls_t;

struct tcp_keepalive {
  int keepalive_enabled;
  int keepalive_idle;
  int keepalive_count;
  int keepalive_intvl;
};

typedef struct server_struc {
  struct server_struc *next, *prev;

  struct pool_rec *pool;
  xaset_t *set;

  const char *ServerName;
  const char *ServerAddress;
  const char *ServerFQDN;

  unsigned int ServerPort;

  struct tcp_keepalive *tcp_keepalive;

  int tcp_mss_len, tcp_reuse_port;

  int tcp_rcvbuf_len;
  unsigned char tcp_rcvbuf_override;

  int tcp_sndbuf_len;
  unsigned char tcp_sndbuf_override;

  const char *ServerAdmin;

  const pr_netaddr_t *addr;

  struct conn_struc *listen;

  xaset_t *conf;
  int config_type;

  unsigned int sid;

  pr_table_t *notes;

} server_rec;

typedef struct cmd_struc {
  struct pool_rec *pool;
  server_rec *server;
  config_rec *config;
  struct pool_rec *tmp_pool;
  unsigned int argc;

  char *arg;
  void **argv;

  char *group;

  int cmd_class;

  int stash_index;
  unsigned int stash_hash;

  pr_table_t *notes;

  int cmd_id;

  int is_ftp;
  const char *protocol;

} cmd_rec;

