import random
import struct
from typing import List

# Target: generate valid IPv4/IPv6 presentation strings for pr_inet_pton fuzzer.
# The harness picks AF randomly and consumes FUZZ_PARAM_STR(), so we return a
# single buffer that will be used as that string. We bias toward valid literals
# and include a mix of IPv4 and IPv6 formats that inet_pton accepts.

RFC_3849_DOC_V6 = [
    "2001:db8::1", "2001:db8:0:0:1::", "2001:db8:85a3::8a2e:370:7334",
    "2001:db8::dead:beef", "2001:db8:aaaa:bbbb:cccc:dddd:eeee:ffff",
]
RFC_5737_DOC_V4 = [
    "192.0.2.1", "198.51.100.42", "203.0.113.5", "192.0.2.255",
]

# Some interesting IPv6 edge cases (still valid):
INTERESTING_V6 = [
    "::",                 # all-zero
    "::1",                # loopback
    "ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff",  # max
    "::ffff:192.0.2.128", # IPv4-mapped
    "2001:db8::",         # compressed tail
    "fe80::1",            # link-local (no scope id appended)
    "2001:db8:0:0:0:0:0:1", # full form
]

# Some interesting IPv4 cases:
INTERESTING_V4 = [
    "0.0.0.0",
    "127.0.0.1",
    "255.255.255.255",
    "1.2.3.4",
    "10.0.0.1",
    "172.16.0.1",
    "192.168.1.1",
]


def _rand_ipv4(rng: random.Random) -> str:
    # Mix from curated plus random dotted quad
    choice_pool = RFC_5737_DOC_V4 + INTERESTING_V4
    if rng.random() < 0.6:
        return rng.choice(choice_pool)
    # random dotted quad in valid range
    octets = [rng.randrange(0, 256) for _ in range(4)]
    return "%d.%d.%d.%d" % tuple(octets)


def _hextet(rng: random.Random) -> str:
    return format(rng.randrange(0, 0x10000), 'x')


def _rand_ipv6(rng: random.Random) -> str:
    # Bias toward valid and diverse encodings
    if rng.random() < 0.5:
        return rng.choice(RFC_3849_DOC_V6 + INTERESTING_V6)

    mode = rng.randrange(0, 5)
    if mode == 0:
        # Full 8 hextets
        return ":".join(_hextet(rng) for _ in range(8))
    elif mode == 1:
        # Compressed with :: at a random position
        left_count = rng.randrange(0, 7)
        right_count = rng.randrange(0, 7 - left_count)
        left = ":".join(_hextet(rng) for _ in range(left_count))
        right = ":".join(_hextet(rng) for _ in range(right_count))
        if left and right:
            return f"{left}::${right}".replace("$", "")
        elif left:
            return f"{left}::"
        elif right:
            return f"::${right}".replace("$", "")
        else:
            return "::"
    elif mode == 2:
        # IPv4-mapped
        v4 = _rand_ipv4(rng)
        left_count = rng.randrange(0, 6)  # ensure overall valid length when mapped
        left = ":".join(_hextet(rng) for _ in range(left_count))
        prefix = left + (":" if left else "")
        return f"{prefix}::ffff:{v4}" if rng.random() < 0.7 else f"{prefix}{v4}"
    elif mode == 3:
        # Leading-zero padded hextets (still valid)
        parts = [format(rng.randrange(0, 0x10000), '04x') for _ in range(8)]
        return ":".join(parts)
    else:
        # Single run compressed, rest full
        run_len = rng.randrange(1, 7)
        start = rng.randrange(0, 8 - run_len)
        parts: List[str] = []
        for i in range(8):
            if start <= i < start + run_len:
                if i == start:
                    parts.append("")  # will create :: after join tweaks
                continue
            parts.append(_hextet(rng))
        # Build with '::' correctly
        s = ":".join(parts)
        s = s.replace(":::", "::")
        if s.startswith(":"):
            s = ":" + s
        if s.endswith(":"):
            s = s + ":"
        if "::" not in s:
            s = s.replace("::", "::")
        return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose whether to produce IPv4 or IPv6 string; harness chooses AF randomly,
    # so either is acceptable. Provide a slight bias to IPv6 for broader code paths.
    if rng.random() < 0.6:
        s = _rand_ipv6(rng)
    else:
        s = _rand_ipv4(rng)

    # Ensure NUL-terminated C-string buffer semantics by including only the text;
    # the fuzzing harness will treat the bytes as a std::string, which stores
    # length separately; no explicit NUL needed. But keep under 4 KiB.
    b = s.encode('ascii')[:4096]
    return b
